function a(){const r=document.querySelectorAll('[data-component="lazy-youtube"]');r.length!==0&&r.forEach(t=>{const l=t.getAttribute("data-embed");l&&t.addEventListener("click",o=>{o.preventDefault();const e=document.createElement("iframe");e.src=`https://www.youtube.com/embed/${l}?rel=0&showinfo=0&autoplay=1`,e.title="YouTube video player",e.className="w-full h-full absolute inset-0 border-0 rounded-xl loaded z-20",e.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",e.referrerPolicy="strict-origin-when-cross-origin",e.allowFullscreen=!0,t.innerHTML="",t.appendChild(e),t.classList.add("playing")})})}export{a as initLazyYoutube};
